import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent, VlLinkComponent } from '@domg-wc/components/atom';
import { VlProzaMessage, VlProzaMessagePreloader } from '@domg-wc/components/block';

registerWebComponents([VlProzaMessagePreloader, VlProzaMessage, VlButtonComponent, VlLinkComponent]);

// vl-proza-message-preloader haalt alle berichten van het domein in één request op bij proza/domein/{domain},
// relatief tov de huidige url of achter base-url, en zet ze in een cache. vl-proza-message zoekt daar eerst en
// vraagt een bericht enkel apart op als het er niet in zit. In Storybook antwoordt een mock voor mockdomain.

// Zonder element kan het ook in code, bv. bij het opstarten, als je de volgorde of het moment wil bepalen:
// VlProzaMessagePreloader.preload('mockdomain');
